// src/services/ContractService.ts
// Serwis zarządzania kontraktami

import { AppDataSource } from '../config/database';
import { Contract, ContractStatus } from '../entities/Contract';
import { User } from '../entities/User';
import { Repository } from 'typeorm';

export class ContractService {
  private contractRepository: Repository<Contract>;

  constructor() {
    this.contractRepository = AppDataSource.getRepository(Contract);
  }

  /**
   * Walidacja numeru kontraktu w formacie RXXXXXXX_Y
   * R = prefix
   * XXXXXXX = 7-cyfrowy numer (0000001-9999999)
   * _Y = litera rewizji/wersji (A-Z)
   */
  validateContractNumber(contractNumber: string): boolean {
    const regex = /^R\d{7}_[A-Z]$/;
    return regex.test(contractNumber);
  }

  /**
   * Generowanie kolejnego numeru kontraktu
   */
  async generateContractNumber(): Promise<string> {
    // Pobierz ostatni numer kontraktu
    const lastContract = await this.contractRepository
      .createQueryBuilder('contract')
      .orderBy('contract.id', 'DESC')
      .limit(1)
      .getOne();

    let nextNumber = 1;
    let revisionLetter = 'A';  // Domyślnie wersja A

    if (lastContract && lastContract.contractNumber) {
      // Wyciągnij numer z formatu RXXXXXXX_Y
      const match = lastContract.contractNumber.match(/^R(\d{7})_([A-Z])$/);
      if (match) {
        const baseNumber = parseInt(match[1], 10);
        nextNumber = baseNumber + 1;
      }
    }

    // Format: R0000001_A (domyślnie wersja A)
    const paddedNumber = nextNumber.toString().padStart(7, '0');
    return `R${paddedNumber}_${revisionLetter}`;
  }

  /**
   * Utworzenie nowego kontraktu
   */
  async createContract(
    data: {
      contractNumber?: string;
      customName: string;
      orderDate: Date;
      managerCode: string;
      projectManagerId: number;
      jowiszRef?: string;
      liniaKolejowa?: string;
    },
    createdById?: number
  ): Promise<Contract> {
    // Jeśli nie podano numeru, wygeneruj automatycznie
    const contractNumber = data.contractNumber || await this.generateContractNumber();

    // Walidacja numeru
    if (!this.validateContractNumber(contractNumber)) {
      throw new Error('Nieprawidłowy format numeru kontraktu. Oczekiwano: RXXXXXXX_Y');
    }

    // Sprawdź czy numer już istnieje
    const existing = await this.contractRepository.findOne({
      where: { contractNumber }
    });

    if (existing) {
      throw new Error(`Kontrakt o numerze ${contractNumber} już istnieje`);
    }

    // Sprawdź czy kierownik projektu istnieje
    const userRepository = AppDataSource.getRepository(User);
    const manager = await userRepository.findOne({
      where: { id: data.projectManagerId }
    });

    if (!manager) {
      throw new Error('Kierownik projektu nie istnieje');
    }

    // Utworzenie kontraktu
    const contract = this.contractRepository.create({
      contractNumber,
      customName: data.customName,
      orderDate: data.orderDate,
      managerCode: data.managerCode,
      projectManagerId: data.projectManagerId,
      jowiszRef: data.jowiszRef,
      liniaKolejowa: data.liniaKolejowa,
      status: ContractStatus.CREATED
    });

    const savedContract = await this.contractRepository.save(contract);

    // Wyślij powiadomienie o utworzeniu kontraktu
    if (createdById) {
      try {
        const ContractNotificationService = (await import('./ContractNotificationService')).default;
        await ContractNotificationService.notifyContractCreated(savedContract.id, createdById);
      } catch (error) {
        console.error('❌ Błąd wysyłania powiadomienia o utworzeniu kontraktu:', error);
        // Nie przerywamy procesu, jeśli powiadomienie się nie uda
      }
    }

    return savedContract;
  }

  /**
   * Pobranie kontraktu po ID
   */
  async getContractById(id: number): Promise<Contract | null> {
    return await this.contractRepository.findOne({
      where: { id },
      relations: ['projectManager', 'subsystems', 'subsystems.tasks']
    });
  }

  /**
   * Pobranie kontraktu po numerze
   */
  async getContractByNumber(contractNumber: string): Promise<Contract | null> {
    return await this.contractRepository.findOne({
      where: { contractNumber },
      relations: ['projectManager', 'subsystems', 'subsystems.tasks']
    });
  }

  /**
   * Lista wszystkich kontraktów
   */
  async getAllContracts(
    filters?: {
      status?: ContractStatus;
      projectManagerId?: number;
      search?: string;
    },
    options?: {
      sortBy?: string;
      sortOrder?: 'ASC' | 'DESC';
      page?: number;
      limit?: number;
    }
  ): Promise<{
    contracts: Contract[];
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  }> {
    // Column mapping for sorting
    const columnMap: Record<string, string> = {
      id: 'contract.id',
      contractNumber: 'contract.contractNumber',
      customName: 'contract.customName',
      orderDate: 'contract.orderDate',
      managerCode: 'contract.managerCode',
      status: 'contract.status',
      createdAt: 'contract.createdAt',
      updatedAt: 'contract.updatedAt'
    };

    const query = this.contractRepository
      .createQueryBuilder('contract')
      .leftJoinAndSelect('contract.projectManager', 'projectManager')
      .leftJoinAndSelect('contract.subsystems', 'subsystems');

    if (filters?.status) {
      query.andWhere('contract.status = :status', { status: filters.status });
    }

    if (filters?.projectManagerId) {
      query.andWhere('contract.projectManagerId = :projectManagerId', {
        projectManagerId: filters.projectManagerId
      });
    }

    if (filters?.search) {
      const searchLower = filters.search.toLowerCase();
      query.andWhere(
        '(LOWER(contract.contractNumber) LIKE :search OR LOWER(contract.customName) LIKE :search OR LOWER(contract.managerCode) LIKE :search)',
        { search: `%${searchLower}%` }
      );
    }

    // Sorting with validation
    const sortBy = options?.sortBy || 'createdAt';
    const sortOrder = options?.sortOrder || 'DESC';
    if (sortBy === 'subsystemsCount') {
      query
        .addSelect(
          `(SELECT COUNT(*) FROM subsystems WHERE subsystems.contract_id = contract.id)`,
          'subsystemsCount'
        )
        .orderBy('"subsystemsCount"', sortOrder);
    } else {
      const sortColumn = columnMap[sortBy] || 'contract.createdAt';
      query.orderBy(sortColumn, sortOrder);
    }

    // Pagination
    const page = Math.max(1, options?.page || 1);
    const limit = Math.min(100, Math.max(1, options?.limit || 20));
    const skip = (page - 1) * limit;

    const [contracts, total] = await query
      .skip(skip)
      .take(limit)
      .getManyAndCount();

    return {
      contracts,
      total,
      page,
      limit,
      totalPages: limit > 0 ? Math.ceil(total / limit) : 0
    };
  }

  /**
   * Aktualizacja kontraktu
   */
  async updateContract(id: number, data: Partial<Contract>): Promise<Contract> {
    const contract = await this.getContractById(id);
    if (!contract) {
      throw new Error('Kontrakt nie znaleziony');
    }

    // Nie pozwól na zmianę numeru kontraktu
    if (data.contractNumber && data.contractNumber !== contract.contractNumber) {
      throw new Error('Nie można zmienić numeru kontraktu');
    }

    Object.assign(contract, data);
    return await this.contractRepository.save(contract);
  }

  /**
   * Zatwierdzenie kontraktu
   */
  async approveContract(id: number, approvedById?: number): Promise<Contract> {
    const contract = await this.getContractById(id);
    if (!contract) {
      throw new Error('Kontrakt nie znaleziony');
    }

    if (contract.status !== ContractStatus.CREATED) {
      throw new Error('Tylko kontrakty w statusie CREATED mogą być zatwierdzone');
    }

    contract.status = ContractStatus.APPROVED;
    const savedContract = await this.contractRepository.save(contract);

    // Wyślij powiadomienie o zatwierdzeniu kontraktu
    if (approvedById) {
      try {
        const ContractNotificationService = (await import('./ContractNotificationService')).default;
        await ContractNotificationService.notifyContractApproved(savedContract.id, approvedById);
      } catch (error) {
        console.error('❌ Błąd wysyłania powiadomienia o zatwierdzeniu kontraktu:', error);
        // Nie przerywamy procesu, jeśli powiadomienie się nie uda
      }
    }

    return savedContract;
  }

  /**
   * Usunięcie kontraktu
   */
  async deleteContract(id: number): Promise<void> {
    const contract = await this.getContractById(id);
    if (!contract) {
      throw new Error('Kontrakt nie znaleziony');
    }

    // Sprawdź czy kontrakt ma podsystemy
    if (contract.subsystems && contract.subsystems.length > 0) {
      throw new Error('Nie można usunąć kontraktu posiadającego podsystemy');
    }

    await this.contractRepository.remove(contract);
  }

  /**
   * Statystyki kontraktów
   */
  async getStats(): Promise<{ total: number; byStatus: Record<string, number> }> {
    const contracts = await this.contractRepository.find();

    const byStatus: Record<string, number> = {
      CREATED: 0,
      PENDING_CONFIGURATION: 0,
      APPROVED: 0,
      IN_PROGRESS: 0,
      COMPLETED: 0,
      CANCELLED: 0
    };

    contracts.forEach(c => {
      byStatus[c.status] = (byStatus[c.status] || 0) + 1;
    });

    return {
      total: contracts.length,
      byStatus
    };
  }
}

